require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role(['HOD']);
$user=current_user();$dept=$pdo->prepare('SELECT * FROM departments WHERE hod_user_id=?');$dept->execute([$user['id']]);$dept=$dept->fetch();
$pending=$pdo->prepare('SELECT COUNT(*) FROM department_clearances dc JOIN clearance_requests cr ON cr.id=dc.request_id WHERE dc.department_id=? AND dc.status=\'Approved\' AND NOT EXISTS(SELECT 1 FROM approvals a WHERE a.request_id=cr.id AND a.role=\'HOD\' AND a.department_id=dc.department_id)');$pending->execute([$dept['id']]);$pending=$pending->fetchColumn();
$approved=$pdo->prepare('SELECT COUNT(*) FROM approvals WHERE approver_user_id=? AND role=\'HOD\' AND status=\'Approved\'');$approved->execute([$user['id']]);$approved=$approved->fetchColumn();
$rejected=$pdo->prepare('SELECT COUNT(*) FROM approvals WHERE approver_user_id=? AND role=\'HOD\' AND status=\'Rejected\'');$rejected->execute([$user['id']]);$rejected=$rejected->fetchColumn();
